import csv
import json
import math
import os
from collections import defaultdict

INPUT = '/root/trivy_report.json'
OUTPUT = '/root/security_audit.csv'
FIELDS = ['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url']
ALLOWED = {'HIGH', 'CRITICAL'}
SOURCES = ('nvd', 'ghsa', 'redhat')


def nonempty(value):
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def cvss_score(vulnerability):
    cvss = vulnerability.get('CVSS')
    if not isinstance(cvss, dict):
        return 'N/A'
    for source in SOURCES:
        record = cvss.get(source)
        if not isinstance(record, dict):
            continue
        for key in ('V3Score', 'V3.1Score', 'V3_1Score'):
            value = record.get(key)
            if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value):
                return f'{float(value):.1f}'
    for source in SOURCES:
        record = cvss.get(source)
        if not isinstance(record, dict):
            continue
        for key in ('V2Score', 'V2.0Score', 'V2_0Score'):
            value = record.get(key)
            if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value):
                return f'{float(value):.1f}'
    return 'N/A'


with open(INPUT, encoding='utf-8') as handle:
    report = json.load(handle)

eligible = []
for result in report.get('Results', []):
    if not isinstance(result, dict):
        continue
    vulnerabilities = result.get('Vulnerabilities') or []
    if not isinstance(vulnerabilities, list):
        raise ValueError('Result Vulnerabilities must be a list or null')
    for vulnerability in vulnerabilities:
        if not isinstance(vulnerability, dict):
            raise ValueError('Vulnerability entry must be an object')
        severity = nonempty(vulnerability.get('Severity'))
        if severity is None or severity.upper() not in ALLOWED:
            continue
        package = nonempty(vulnerability.get('PkgName')) or nonempty(vulnerability.get('name'))
        version = nonempty(vulnerability.get('InstalledVersion')) or nonempty(vulnerability.get('version'))
        cve_id = nonempty(vulnerability.get('VulnerabilityID')) or nonempty(vulnerability.get('CVE'))
        if not package or not version or not cve_id:
            raise ValueError(f'Eligible finding missing identity fields: {vulnerability!r}')
        title = (nonempty(vulnerability.get('Title'))
                 or nonempty(vulnerability.get('Description'))
                 or cve_id)
        references = vulnerability.get('References')
        reference_url = None
        if isinstance(references, list):
            reference_url = next((nonempty(url) for url in references if nonempty(url)), None)
        url = nonempty(vulnerability.get('PrimaryURL')) or reference_url or 'N/A'
        fixed_version = nonempty(vulnerability.get('FixedVersion')) or 'N/A'
        eligible.append({
            'Package': package,
            'Version': version,
            'CVE_ID': cve_id,
            'Severity': severity.upper(),
            'CVSS_Score': cvss_score(vulnerability),
            'Fixed_Version': fixed_version,
            'Title': title,
            'Url': url,
        })

by_key = defaultdict(list)
for record in eligible:
    by_key[(record['Package'], record['CVE_ID'])].append(record)

# Selecting the sorted first record makes duplicate scanner entries deterministic.
rows = [sorted(records, key=lambda record: tuple(record[field] for field in FIELDS))[0]
        for records in by_key.values()]
rows.sort(key=lambda record: (record['Package'], record['CVE_ID'], record['Version'], record['Severity']))

with open(OUTPUT, 'w', encoding='utf-8', newline='') as handle:
    writer = csv.DictWriter(handle, fieldnames=FIELDS, extrasaction='raise')
    writer.writeheader()
    writer.writerows(rows)

if not os.path.isfile(OUTPUT):
    raise AssertionError('CSV artifact was not created')
with open(OUTPUT, encoding='utf-8', newline='') as handle:
    reader = csv.DictReader(handle)
    if reader.fieldnames != FIELDS:
        raise AssertionError(f'Unexpected header: {reader.fieldnames!r}')
    parsed = list(reader)

if any(set(row) != set(FIELDS) for row in parsed):
    raise AssertionError('CSV row has an unexpected column set')
if any(not row['Package'] or not row['Version'] or not row['CVE_ID'] for row in parsed):
    raise AssertionError('CSV contains an empty identity field')
if any(row['Severity'] not in ALLOWED for row in parsed):
    raise AssertionError('CSV contains a disallowed severity')
if any(not row['Fixed_Version'] or not row['CVSS_Score'] for row in parsed):
    raise AssertionError('CSV contains an empty fixed version or CVSS value')
keys = [(row['Package'], row['CVE_ID']) for row in parsed]
if len(keys) != len(set(keys)):
    raise AssertionError('CSV contains duplicate package/CVE pairs')
expected_keys = set(by_key)
if set(keys) != expected_keys:
    raise AssertionError(f'CSV keys differ from eligible findings: {set(keys)!r} != {expected_keys!r}')
expected_order = sorted(parsed, key=lambda row: (row['Package'], row['CVE_ID'], row['Version'], row['Severity']))
if parsed != expected_order:
    raise AssertionError('CSV rows are not in deterministic order')

print(f'eligible_findings={len(eligible)}')
print(f'deduplicated_rows={len(rows)}')
print(f'output={OUTPUT}')
